alter table public.coaching_start_resources add column if not exists learning_design jsonb;
alter table public.coaching_start_resources add constraint playbook_learning_design_object check (learning_design is null or jsonb_typeof(learning_design) = 'object');
comment on column public.coaching_start_resources.learning_design is 'Coach-editable visual lesson content; text only, rendered with escaping. Existing ownership and publication RLS applies.';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "A missed session is a scheduling problem.", "deck": "Keep the next useful training stimulus. Drop the urge to repay exercise debt.", "minutes": 3, "visual": {"type": "sequence", "title": "The next-session decision", "nodes": [{"label": "Missed", "text": "One planned session did not happen."}, {"label": "Rebook", "text": "Find a genuine slot with recovery between sessions."}, {"label": "Resume", "text": "If there is no slot, use the next planned session."}], "caption": "A scheduling framework, not a prediction of muscle loss."}, "science": "Resistance-training adaptations do not disappear overnight. A controlled maintenance study found some adaptations persisted with reduced training, with differences by age and outcome.", "limitation": "That study does not tell us exactly how many sessions you can skip. This rebooking rule is a coaching application, not a tested protocol.", "decision": {"question": "What does the rest of your week actually allow?", "choices": [{"label": "A clear spare slot", "answer": "Move the missed session only if the remaining sessions still have sensible spacing. Avoid doubling the work."}, {"label": "No spare slot", "answer": "Resume the next assigned session. Record the missed one honestly so your coach can see the pattern."}, {"label": "Pain or illness", "answer": "Do not squeeze in a catch-up. Stop and seek appropriate advice; return when safe."}]}, "case": {"context": "A hearing runs over on Tuesday. Thursday and Saturday training are still realistic.", "action": "Keep Thursday and Saturday. Do not turn Wednesday into a rushed catch-up plus Thursday into another hard session.", "reason": "The plan survives the week without a recovery bottleneck."}, "steps": ["Look at the whole week before moving anything.", "Keep the warm-up and prescribed recovery between sessions.", "If this happens repeatedly, change the timetable with your coach."], "takeaway": "Miss one session. Make one sensible decision. Keep going.", "pdf_file": "missed-workout-7bf0facfc6e0.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Bickel et al. (2011) · Retaining resistance-training adaptations · Exercise trial", "url": "https://pubmed.ncbi.nlm.nih.gov/21131862/"}]$lesson$::jsonb, description=$lesson$Keep the next useful training stimulus. Drop the urge to repay exercise debt.$lesson$, quick_answer=$lesson$Miss one session. Make one sensible decision. Keep going.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='missed-workout';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Twenty minutes can still count.", "deck": "Protect the important work instead of cramming a full session into less time.", "minutes": 3, "visual": {"type": "priority", "title": "What stays when time shrinks?", "nodes": [{"label": "Keep", "text": "Warm-up and the coach-selected priority lifts."}, {"label": "Reduce", "text": "Use only the shorter set scheme your coach approved."}, {"label": "Leave", "text": "Optional extras; they are not a debt for tomorrow."}], "caption": "Priority order, not a universal 20-minute prescription."}, "science": "A large review found many resistance-training prescriptions improved strength and muscle size compared with no training. More work can matter, but one ideal schedule is not required to benefit.", "limitation": "The review did not test this exact 20-minute session. Exercise choice, load and set reductions need to fit your assigned plan.", "decision": {"question": "What is your limiting factor today?", "choices": [{"label": "Time, but I feel well", "answer": "Open workout options and choose the approved short version. If none exists, ask for one rather than inventing heavy supersets."}, {"label": "No familiar equipment", "answer": "Use a coach-approved alternative. An unfamiliar lift is not automatically interchangeable."}, {"label": "Pain, dizziness or illness", "answer": "Stop. A short workout is not the solution to a safety concern."}]}, "case": {"context": "You have a 25-minute gap before a client call, including changing time.", "action": "Choose a saved short option that fits the actual training window. Start the warm-up immediately.", "reason": "A clear finish time prevents rushed repetitions and skipped preparation."}, "steps": ["Count changing and travel time before choosing a session.", "Keep the prescribed technique and rest; do not race the clock.", "Log what you actually completed, not the full scheduled workout."], "takeaway": "Do less of the right work, with the same attention to execution.", "pdf_file": "emergency-workout-85243fed4c3e.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Currier et al. (2023) · Resistance training prescriptions · Systematic review & network meta-analysis", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10579494/"}]$lesson$::jsonb, description=$lesson$Protect the important work instead of cramming a full session into less time.$lesson$, quick_answer=$lesson$Do less of the right work, with the same attention to execution.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='emergency-workout';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Plan for the week you have.", "deck": "A closing deadline changes capacity. It should change the plan before it breaks the plan.", "minutes": 3, "visual": {"type": "priority", "title": "Three levels of capacity", "nodes": [{"label": "Normal", "text": "Your full assigned schedule fits."}, {"label": "Constrained", "text": "Fewer slots: protect the priority sessions."}, {"label": "Survival", "text": "Sleep, regular meals and safe movement come first."}], "caption": "Capacity levels are a planning tool, not biological thresholds."}, "science": "Maintenance research suggests reduced training can retain some adaptations. The required dose varies with age, training history and the outcome being maintained.", "limitation": "A 60-hour working week is not a scientific cutoff. This framework does not guarantee maintenance or justify pushing through exhaustion.", "decision": {"question": "Which week are you facing?", "choices": [{"label": "Two reliable windows", "answer": "Put those windows in your calendar now. Agree which assigned sessions take priority; leave room for recovery."}, {"label": "Only one short window", "answer": "Use an approved short option. Tell your coach early so the week can be deliberately adjusted."}, {"label": "Unsafe fatigue or illness", "answer": "Prioritise recovery. Do not drive or train through dangerous sleepiness."}]}, "case": {"context": "A transaction closes Friday. Evenings are unpredictable, but two mornings are protected.", "action": "Book the morning sessions and arrange a repeatable office meal before Monday.", "reason": "You remove two recurring decisions from the busiest part of the day."}, "steps": ["Identify immovable work commitments.", "Book realistic sessions and a backup slot.", "Tell your coach the constraint before the week begins."], "takeaway": "A deliberately smaller week is easier to recover from than an accidental collapse.", "pdf_file": "demanding-week-97eb1c9cb220.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Bickel et al. (2011) · Retaining resistance-training adaptations · Exercise trial", "url": "https://pubmed.ncbi.nlm.nih.gov/21131862/"}]$lesson$::jsonb, description=$lesson$A closing deadline changes capacity. It should change the plan before it breaks the plan.$lesson$, quick_answer=$lesson$A deliberately smaller week is easier to recover from than an accidental collapse.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='demanding-week';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Keep the pattern. Adapt the setting.", "deck": "Your hotel gym is a different environment, not a reason to invent a new programme.", "minutes": 3, "visual": {"type": "sequence", "title": "Travel changes the setup", "nodes": [{"label": "Check", "text": "What equipment and time are actually available?"}, {"label": "Match", "text": "Select an approved option for that setting."}, {"label": "Return", "text": "Resume your normal plan after the trip."}], "caption": "A travel workflow; equipment pictures are not exercise prescriptions."}, "science": "Resistance exercise can be effective across different prescriptions. Consistent, progressive training matters more than reproducing a familiar gym perfectly on one trip.", "limitation": "This is a practical inference from training research. A machine, dumbbell and bodyweight exercise are not identical in loading or skill demands.", "decision": {"question": "What is available on this trip?", "choices": [{"label": "A suitable hotel gym", "answer": "Use the approved hotel option. Keep movement instructions and load selection from your coach."}, {"label": "Only a room", "answer": "Check for a home or room option. If none is assigned, walking and normal daily movement can bridge the trip."}, {"label": "Late arrival and little sleep", "answer": "Do not force a hard session to keep a streak. Choose recovery and replan the next useful slot."}]}, "case": {"context": "You land late, then have a breakfast meeting and an afternoon gap.", "action": "Check the gym once, then use the approved afternoon option rather than sacrificing sleep for an early session.", "reason": "The decision fits both the trip and your recovery."}, "steps": ["Check equipment before the trip if possible.", "Protect one realistic training window.", "Record substitutions and actual work for your coach."], "takeaway": "Take a workable version of your plan with you.", "pdf_file": "travel-training-cf06e606aabf.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Currier et al. (2023) · Resistance training prescriptions · Systematic review & network meta-analysis", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10579494/"}]$lesson$::jsonb, description=$lesson$Your hotel gym is a different environment, not a reason to invent a new programme.$lesson$, quick_answer=$lesson$Take a workable version of your plan with you.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='travel-training';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Do not leave dinner to 9 pm hunger.", "deck": "Build a reliable meal decision before meetings take the decision away.", "minutes": 3, "visual": {"type": "plate", "title": "A useful office meal", "nodes": [{"label": "Protein", "text": "A familiar source that fits your plan and restrictions."}, {"label": "Plants", "text": "Fruit or vegetables in a practical form."}, {"label": "Energy", "text": "Carbohydrate and fats in portions that fit your plan."}], "caption": "Meal components, not fixed plate proportions or calorie targets."}, "science": "Protein provides amino acids used in tissue repair and adaptation. Total daily intake matters; a supplement is not essential when food can meet your needs.", "limitation": "The protein position stand concerns healthy exercising adults. It does not give you a personal target or make one meal automatically balanced.", "decision": {"question": "How late is the evening likely to run?", "choices": [{"label": "I know by lunchtime", "answer": "Choose or pack dinner now. Check the assigned meal first, then use a familiar equivalent that respects your restrictions."}, {"label": "It changed unexpectedly", "answer": "Order a recognisable protein-led meal with vegetables and a practical carbohydrate. Avoid turning hunger into an all-or-nothing decision."}, {"label": "There is no fridge", "answer": "Choose suitable shelf-stable options. Perishable food needs proper temperature control; a desk drawer is not a fridge."}]}, "case": {"context": "You usually eat at 7 pm, but a partner adds a 7:30 call.", "action": "Eat your planned dinner before the call or arrange a suitable delivery in advance.", "reason": "Timing is organised around work instead of waiting until hunger makes the order harder."}, "steps": ["Keep one trusted order saved.", "Make allergies and dietary requirements explicit when ordering.", "Use the meal plan as the reference; do not compensate tomorrow."], "takeaway": "Decide dinner while you still have attention to spare.", "pdf_file": "late-office-e170a0c35392.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "ISSN (2017) · Protein and exercise · Position stand", "url": "https://doi.org/10.1186/s12970-017-0177-8"}]$lesson$::jsonb, description=$lesson$Build a reliable meal decision before meetings take the decision away.$lesson$, quick_answer=$lesson$Decide dinner while you still have attention to spare.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='late-office';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Order with a structure, not a rulebook.", "deck": "Enjoy the meal and make the important choices deliberately.", "minutes": 3, "visual": {"type": "plate", "title": "Build the order in three passes", "nodes": [{"label": "Anchor", "text": "Choose a protein source you enjoy and can eat."}, {"label": "Complete", "text": "Add vegetables and a suitable carbohydrate."}, {"label": "Choose", "text": "Decide which extras you actually want."}], "caption": "A decision aid, not an instruction to remove every sauce or carbohydrate."}, "science": "Energy balance influences weight change over time. An eating pattern you can sustain matters more than treating one restaurant meal as a pass-or-fail test.", "limitation": "Restaurant portions and recipes vary. This guide cannot estimate calories precisely or verify allergen safety.", "decision": {"question": "What kind of meal is this?", "choices": [{"label": "A routine business lunch", "answer": "Pick a familiar main meal that fits your usual structure. If portions are large, stop at comfortable fullness; taking leftovers is optional."}, {"label": "A special dinner", "answer": "Choose the course or drink you most want. Eat normally earlier in the day; do not arrive deliberately starved."}, {"label": "Dietary restrictions", "answer": "Check ingredients and preparation with the venue. For kosher needs, suitable certification and meat/dairy separation cannot be inferred from a menu name."}]}, "case": {"context": "A client selects an Italian restaurant. You still want to stay close to your plan.", "action": "Choose a suitable main and vegetables, then decide whether dessert or drinks matter to you tonight.", "reason": "A clear choice is easier than trying to classify the entire menu as good or bad."}, "steps": ["Check the menu before arriving if useful.", "State dietary requirements clearly.", "Return to your usual next meal, regardless of what you ordered."], "takeaway": "One meal can fit a good week without being a perfect meal.", "pdf_file": "restaurants-47c7ceb24bf9.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "NIDDK · Eating and physical activity for weight management · Clinical education", "url": "https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/eating-physical-activity"}]$lesson$::jsonb, description=$lesson$Enjoy the meal and make the important choices deliberately.$lesson$, quick_answer=$lesson$One meal can fit a good week without being a perfect meal.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='restaurants';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Plan the gaps between meals.", "deck": "Flights and meetings create long gaps. Solve the gaps before you solve the whole trip.", "minutes": 3, "visual": {"type": "sequence", "title": "Three travel checkpoints", "nodes": [{"label": "Before", "text": "Eat normally; pack an appropriate backup."}, {"label": "During", "text": "Use a planned meal or trusted option."}, {"label": "After", "text": "Resume the next ordinary meal at your destination."}], "caption": "A meal-access timeline, not a fasting schedule."}, "science": "A sustainable eating pattern includes a variety of foods and accounts for the environment you actually live in. Travel planning is a way to make that pattern easier to follow.", "limitation": "The specific packing workflow is coaching practice. It has not been shown to guarantee weight loss or prevent fatigue.", "decision": {"question": "Where is the biggest food gap?", "choices": [{"label": "Airport or train", "answer": "Check a suitable option before leaving. Carry a safe backup that meets your restrictions; do not rely on an unknown lounge menu."}, {"label": "Back-to-back meetings", "answer": "Put lunch on the calendar and confirm where it will come from. A portable meal may be more realistic than a sit-down lunch."}, {"label": "Hotel evenings", "answer": "Find one reliable nearby order and one breakfast option. You do not need seven completely different meals."}]}, "case": {"context": "A morning flight is followed immediately by a conference and networking dinner.", "action": "Arrange lunch in advance and carry a suitable backup. Treat dinner as the next meal, not a reward for eating nothing all day.", "reason": "Meal access is predictable even when the itinerary is not."}, "steps": ["Locate the longest meal gap in the itinerary.", "Prepare one safe backup and one reliable order.", "Keep ordinary hydration; do not use hunger as compensation."], "takeaway": "A dependable fallback beats an elaborate plan you cannot use.", "pdf_file": "travel-food-b4add4717a56.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "NIDDK · Eating and physical activity for weight management · Clinical education", "url": "https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/eating-physical-activity"}]$lesson$::jsonb, description=$lesson$Flights and meetings create long gaps. Solve the gaps before you solve the whole trip.$lesson$, quick_answer=$lesson$A dependable fallback beats an elaborate plan you cannot use.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='travel-food';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Your next meal is the reset.", "deck": "Respond to the pattern without punishing yourself for the episode.", "minutes": 3, "visual": {"type": "sequence", "title": "Break the compensation loop", "nodes": [{"label": "Notice", "text": "Describe what happened without a moral label."}, {"label": "Resume", "text": "Eat your next usual meal and hydrate normally."}, {"label": "Adjust", "text": "Change the trigger: timing, access or portions."}], "caption": "A behaviour framework, not a diagnosis or a claim about your calorie balance."}, "science": "Weight management is affected by the pattern of energy intake and expenditure over time. One larger meal does not by itself tell you the direction of long-term change.", "limitation": "You cannot infer fat gained from tomorrow’s scale reading. This guide does not treat binge eating or other eating disorders.", "decision": {"question": "What happened before the larger meal?", "choices": [{"label": "I skipped meals", "answer": "Resume normal meals. Next time, make the earlier meal easier to access rather than trying to use more willpower at night."}, {"label": "It was a celebration", "answer": "Let it be one event. Resume your usual plan; avoid adding punishment cardio or an extreme fast."}, {"label": "Loss of control happens repeatedly", "answer": "Seek qualified support. Repeated distress, purging or restriction needs more than a meal-planning tip."}]}, "case": {"context": "You eat much more than intended after working through lunch and arriving home late.", "action": "Eat normally the next day and arrange lunch plus a backup dinner for the next late shift.", "reason": "You address the preceding gap instead of repeating it as compensation."}, "steps": ["Avoid punitive restriction or exercise.", "Identify one concrete trigger.", "Make one practical change before the next similar day."], "takeaway": "Use the episode as information. Make the next ordinary meal ordinary.", "pdf_file": "overeating-cc10bccf7a99.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "NIDDK · Eating and physical activity for weight management · Clinical education", "url": "https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/eating-physical-activity"}]$lesson$::jsonb, description=$lesson$Respond to the pattern without punishing yourself for the episode.$lesson$, quick_answer=$lesson$Use the episode as information. Make the next ordinary meal ordinary.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='overeating';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Prepare components. Keep choice.", "deck": "A few reusable ingredients can cover more than one meal without a seven-day menu.", "minutes": 3, "visual": {"type": "plate", "title": "The reusable meal system", "nodes": [{"label": "Base", "text": "Prepare a familiar protein or suitable alternative."}, {"label": "Pair", "text": "Keep vegetables and a carbohydrate available."}, {"label": "Finish", "text": "Change seasoning or assembly to suit the meal."}], "caption": "Components are interchangeable ideas; quantities come from your assigned plan."}, "science": "Healthy eating patterns can take different forms. Choosing a repeatable system that fits your preferences is more useful than chasing a single ideal menu.", "limitation": "Meal preparation is a practical strategy, not evidence that batch cooking itself causes fat loss. Food storage and reheating still matter.", "decision": {"question": "How much preparation is realistic?", "choices": [{"label": "About 15 minutes", "answer": "Use quick ingredients and one repeatable assembly meal. Frozen vegetables and suitable prepared foods can reduce the work."}, {"label": "A longer weekend window", "answer": "Cook a few components, then portion or freeze appropriately. Do not assume cooked food is safe in the fridge for a full week."}, {"label": "No reliable prep window", "answer": "Use two trusted orders and a simple grocery fallback. A workable plan can include food bought out."}]}, "case": {"context": "You dislike seven different daily menus and often have leftovers after dinner.", "action": "Use suitable dinner leftovers for lunch, then vary the vegetables or seasoning instead of cooking another full recipe.", "reason": "The system reduces effort while keeping the assigned portions and dietary needs visible."}, "steps": ["Choose a repeatable meal you actually like.", "Buy ingredients for the number of meals you can store safely.", "Keep a no-prep fallback for the day prep does not happen."], "takeaway": "Repeat the useful parts. Variety does not require starting from scratch.", "pdf_file": "meal-prep-0d386b7a362c.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "NIDDK · Eating and physical activity for weight management · Clinical education", "url": "https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/eating-physical-activity"}]$lesson$::jsonb, description=$lesson$A few reusable ingredients can cover more than one meal without a seven-day menu.$lesson$, quick_answer=$lesson$Repeat the useful parts. Variety does not require starting from scratch.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='meal-prep';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Match the day to your alertness.", "deck": "A poor night is information for today’s choices, not an instruction to chase a recovery score.", "minutes": 3, "visual": {"type": "priority", "title": "Three decisions after poor sleep", "nodes": [{"label": "Safety", "text": "Am I alert enough to drive and train safely?"}, {"label": "Training", "text": "Can I execute the assigned work with control?"}, {"label": "Tonight", "text": "What can I protect about the next sleep opportunity?"}], "caption": "A safety-first decision order, not a wearable readiness calculation."}, "science": "Sleep is regulated by both sleep pressure and circadian timing. Regular sleep schedules and attention to light and caffeine can support the next sleep opportunity.", "limitation": "One routine cannot fix insomnia, sleep apnoea or shift-work problems. Persistent symptoms need clinical assessment.", "decision": {"question": "How do you feel right now?", "choices": [{"label": "Tired but functioning", "answer": "Use the warm-up to assess technique and effort. Choose a coach-approved easier option if needed; avoid attempting a personal record."}, {"label": "Sleepy enough to feel unsafe", "answer": "Do not drive or perform hazardous training. Prioritise safety and arrange appropriate support."}, {"label": "This keeps happening", "answer": "Record the pattern and seek medical advice, especially with loud snoring, gasping or marked daytime sleepiness."}]}, "case": {"context": "A late call leaves you short of sleep before a planned heavy session.", "action": "Assess alertness first. If safe but clearly under-recovered, choose an approved easier session and protect tonight’s bedtime.", "reason": "You reduce unnecessary risk without judging the whole programme by one night."}, "steps": ["Use how you feel and function, not only the watch score.", "Avoid using late caffeine to force a normal evening.", "Keep the next sleep window as regular as your schedule allows."], "takeaway": "Protect safety today and the next sleep opportunity tonight.", "pdf_file": "poor-sleep-8774b387cc9d.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "NHLBI · Healthy sleep habits · Clinical education", "url": "https://www.nhlbi.nih.gov/health/sleep-deprivation/healthy-sleep-habits"}, {"title": "NHLBI · Your sleep/wake cycle · Physiology explained", "url": "https://www.nhlbi.nih.gov/health/sleep/sleep-wake-cycle"}]$lesson$::jsonb, description=$lesson$A poor night is information for today’s choices, not an instruction to chase a recovery score.$lesson$, quick_answer=$lesson$Protect safety today and the next sleep opportunity tonight.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='poor-sleep';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "The scale weighs more than fat.", "deck": "Look for a pattern before reacting to a single morning.", "minutes": 3, "visual": {"type": "trend", "title": "A trend can hide inside daily noise", "nodes": [{"label": "Water", "text": "Salt, carbohydrate storage and hormonal changes can alter water weight."}, {"label": "Contents", "text": "Food, fluids and bowel contents contribute to scale weight."}, {"label": "Tissue", "text": "Longer-term changes may include fat and lean tissue."}], "caption": "Illustrative measurements below are synthetic; they are not your data or a forecast."}, "science": "Body weight reflects multiple compartments. Short-term changes are not a direct measurement of body-fat change, so similar measurement conditions and repeated observations are more useful than one reading.", "limitation": "A trend still cannot separate fat, muscle and fluid precisely. A flat week is not enough evidence to diagnose a fat-loss plateau.", "decision": {"question": "What changed in the reading?", "choices": [{"label": "Up after a meal out", "answer": "Return to normal meals and compare repeated readings under similar conditions. Do not immediately cut calories."}, {"label": "A longer pattern has flattened", "answer": "Review the trend, plan adherence, movement and measurement conditions with your coach before changing targets."}, {"label": "Rapid unexplained change or symptoms", "answer": "Seek medical advice for unexplained rapid changes, swelling or other concerning symptoms."}]}, "case": {"context": "The scale rises after restaurant food even though the overall week has gone well.", "action": "Keep normal meals and review several comparable measurements rather than changing the plan that morning.", "reason": "You avoid mistaking a noisy observation for a change in body composition."}, "steps": ["If weighing, use comparable conditions and a schedule that is comfortable for you.", "Consider training performance, waist measures and how clothes fit alongside weight.", "Do not weigh more often if it worsens distress."], "takeaway": "A single number is a measurement. A repeated pattern is more useful evidence.", "pdf_file": "weight-fluctuations-bafd035226bd.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Hall et al. (2011) · Quantification of energy imbalance · Dynamic weight-change model", "url": "https://www.niddk.nih.gov/research-funding/at-niddk/labs-branches/laboratory-biological-modeling/integrative-physiology-section/research/body-weight-planner"}, {"title": "Kreitzman et al. (1992) · Glycogen storage and weight fluctuations · Physiological review", "url": "https://pubmed.ncbi.nlm.nih.gov/1615908/"}]$lesson$::jsonb, description=$lesson$Look for a pattern before reacting to a single morning.$lesson$, quick_answer=$lesson$A single number is a measurement. A repeated pattern is more useful evidence.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='weight-fluctuations';
update public.coaching_start_resources set learning_design=$lesson${"version": 1, "headline": "Restart at the next useful action.", "deck": "Do not wait for a clean Monday to repair a difficult week.", "minutes": 3, "visual": {"type": "sequence", "title": "Make the restart specific", "nodes": [{"label": "Choose", "text": "One action small enough to do today."}, {"label": "Place", "text": "Decide when and where it will happen."}, {"label": "Backup", "text": "Plan what you will do if work interrupts."}], "caption": "A planning framework, not a promise that habits form in a fixed number of days."}, "science": "Reviews suggest action and coping plans can help physical activity. Effects vary, and a field experiment found that simple scheduling alone did not reliably increase repeated gym attendance.", "limitation": "Planning is a tool, not a guarantee. The action must be feasible, and recurring barriers need changes to the environment or programme.", "decision": {"question": "What can you do next?", "choices": [{"label": "A meal is next", "answer": "Eat the next assigned or suitable ordinary meal. Set up tomorrow’s lunch before the evening gets busy."}, {"label": "A session is next", "answer": "Attend the next realistic assigned session. Use an approved shorter option if the normal session does not fit."}, {"label": "Everything feels too much", "answer": "Pick one achievable action and tell your coach what changed. Simplify the week before adding more tasks."}]}, "case": {"context": "A deadline derails training, meals and check-ins. You feel like waiting until Monday.", "action": "Today: eat the next normal meal. Tomorrow: attend one realistic session. If a call overruns, use the approved backup slot.", "reason": "The restart has a place in the diary and an alternative when work intervenes."}, "steps": ["Write: When ___ happens, I will ___ at ___.", "Make the backup easier than the original action.", "Review the barrier after the action, not before every restart."], "takeaway": "You do not need a new start date. You need a next action.", "pdf_file": "back-on-track-0cb43042d28a.pdf"}$lesson$::jsonb, evidence=$lesson$[{"title": "Peng et al. (2022) · Planning interventions for physical activity · Systematic review & meta-analysis", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9223740/"}, {"title": "Carrera et al. (2018) · Limits of simple exercise plans · Randomised field experiment", "url": "https://pubmed.ncbi.nlm.nih.gov/30336306/"}]$lesson$::jsonb, description=$lesson$Do not wait for a clean Monday to repair a difficult week.$lesson$, quick_answer=$lesson$You do not need a new start date. You need a next action.$lesson$ where coach_id='56bd942e-7baa-42d3-a9c3-5eedcb33f1db' and slug='back-on-track';
